import { KiokuArgs, KiokuData, SkillDetail, skillDetailId, SkillKey } from '../types/KiokuTypes';
import { passiveDetails } from '../utils/helpers';
import { Kioku } from './Kioku';


export class PvPKioku extends Kioku {
    effects: SkillDetail[];
    // Same effects in passive TRIGGER order: ability, then crystalis, then ascensions/portrait/support.
    // PassiveSkill.TriggeringOnBattleStart stable-sorts by IBattleStartTriggerPriority, and only
    // barrier/effect-value-variation/add-turn states override the default, so everything else keeps
    // this list order. Two constraints pin it: the kit's CHARGE (ability) must run before an EX crys
    // GAIN_CHARGE_POINT (Tenebrous Arcana "+1 Magic at battle start" was wiped by CHARGE 0/3), and crys
    // SPD states must come before the other SPD states for the f32 gauge tie-break
    // (fixtures/mirrored-thunder-torrent-ally-first.json). `effects` itself stays crys-first for stats.
    triggerOrderEffects: SkillDetail[];
    private crysKeys = new Set<string>()
    private abilityKeys = new Set<string>()
    private scalableEffects: Map<string, SkillDetail> = new Map()
    private unscalableEffects: Map<string, SkillDetail> = new Map()
    private buffMult = 1;
    private debuffMult = 1;

    constructor(args: KiokuArgs) {
        super(args);
        // NOTE: Passives are applied in order: 
        //  (ability or ascension effect), portrait, support ability, crystalis, 
        //  but to reprocde the floating error FIXED spd has to go first, 
        //  idk if this is special cased or if the order is just different for fixed stats? 
        //  Anyways just have crys first, legit only matters for Tsukasa anyways...

        this.crys.forEach(c => {
            this.addEffect(passiveDetails, "passiveSkillMstId", 0, c, false);
        });
        this.unscalableEffects.forEach((_, key) => this.crysKeys.add(key));

        this.addEffect(passiveDetails, "passiveSkillMstId", this.data.ability_id, this.abilityLvl, true);
        this.scalableEffects.forEach((_, key) => this.abilityKeys.add(key));

        for (let i = 1; i <= this.ascension; i++) {
            const passiveId = this.data[`ascension_${i}_effect_2_id` as keyof KiokuData] as number;
            if (passiveId) this.addEffect(passiveDetails, "passiveSkillMstId", passiveId, 1, true);

        }

        if (this.portrait) {
            this.addEffect(passiveDetails, "passiveSkillMstId", this.portrait.passiveSkill1, 6, false);
        }

        if (this.support && [this.data.role, this.data.element].includes(this.support.data.support_target)) {
            this.addEffect(passiveDetails, "passiveSkillMstId", this.support.data.support_id, this.support.supportLvl, false);
        }

        [...this.unscalableEffects.values(), ...this.scalableEffects.values()].forEach(e => {
            if (e.abilityEffectType === "UP_BUFF_EFFECT_VALUE") {
                this.buffMult += e.value1 / 1000;
            } else if (e.abilityEffectType === "UP_DEBUFF_EFFECT_VALUE") {
                this.debuffMult += e.value1 / 1000;
            } else if (e.abilityEffectType === "DWN_BUFF_EFFECT_VALUE") {
                // [ADDED] confirmed to exist in enums.ts and already handled by the
                // sibling ScoreAttackKioku.ts (which this class doesn't share code
                // with) - PvPKioku.ts was missing the down-side of this pair, so a
                // "reduce this unit's own buff effectiveness" passive/ascension effect
                // would have silently done nothing.
                this.buffMult -= e.value1 / 1000;
            } else if (e.abilityEffectType === "DWN_DEBUFF_EFFECT_VALUE") {
                // [ADDED] same as above, for debuff effectiveness.
                this.debuffMult -= e.value1 / 1000;
            }
        });

        // [ADDED] matches ScoreAttackKioku.ts's own guard - now that
        // DWN_BUFF_EFFECT_VALUE/DWN_DEBUFF_EFFECT_VALUE can push these below 1 (or even
        // negative with a large enough debuff), floor at 0 so a buff/debuff's magnitude
        // can't flip sign entirely.
        if (this.buffMult < 0) this.buffMult = 0;
        if (this.debuffMult < 0) this.debuffMult = 0;

        // [CONFIRMED 3.19] UP/DWN_BUFF/DEBUFF_EFFECT_VALUE are live states applied when a state is GIVEN
        // (PvPTeam.giveTransform), not a one-time rescale of this kioku's passives. Effects from card (portrait) and
        // support sources are never scaled (AbilitySource != Unit); crystalis kept with them as before [UNCERTAIN].
        this.effects = [
            ...[...this.unscalableEffects.values()].map(e => ({ ...e, _noEffectValueScale: true } as unknown as SkillDetail)),
            ...this.scalableEffects.values(),
        ];
        const rank = (e: SkillDetail) => {
            const key = String(skillDetailId(e))
            return this.abilityKeys.has(key) ? 0 : this.crysKeys.has(key) ? 1 : 2
        }
        this.triggerOrderEffects = [0, 1, 2].flatMap(r => this.effects.filter(e => rank(e) === r));
    }

    addEffect(map: Record<any, SkillDetail>, key: SkillKey, id: number, lvl: number, affectedByMult: boolean) {
        const target = affectedByMult ? this.scalableEffects : this.unscalableEffects
        for (const eff of Object.values(map).filter(v => (v as any)[key] === id * 100 + lvl)) {
            // Merge crys with same ID, nothing else has same ID so this is not risky
            const key = String(skillDetailId(eff))
            if (target.has(key)) {
                const old = target.get(key)!
                target.set(key, { ...old, value1: old.value1 + eff.value1 })
            } else {
                target.set(key, eff)
            }
        }
    }
}
